pub(super) fn check_missing_whitespace_around_operator(
    &mut self,
    line: &LogicalLine,
    context: &mut LogicalLinesContext,
) {
    self.operator_parens = 0;
    self.operator_fstrings = 0;
    self.operator_flags = 0;
    self.operator_cursor = 0;
    let mut tokens = line.tokens().iter().peekable();
    let first_token = tokens
        .by_ref()
        .find(|token| !is_non_logical_token(token.kind()));
    let Some(mut prev_token) = first_token else {
        return;
    };
    self.operator_parens = u32::from(matches!(
        prev_token.kind(),
        TokenKind::Lpar | TokenKind::Lambda
    ));
    self.operator_fstrings = u32::from(matches!(prev_token.kind(), TokenKind::FStringStart));

    while let Some(token) = tokens.next() {
        let kind = token.kind();
        let _classified = self.operator_classifies_token(kind);
        self.visit_token_kind(kind);

        if is_non_logical_token(kind) {
            continue;
        }

        match kind {
            TokenKind::FStringStart => {
                self.operator_fstrings = self.operator_fstrings.saturating_add(1);
                self.operator_flags = self.operator_flags.saturating_add(1);
            }
            TokenKind::FStringEnd => {
                self.operator_fstrings = self.operator_fstrings.saturating_sub(1);
                self.operator_flags = self.operator_flags.saturating_add(1);
            }
