pub(super) fn check_missing_whitespace_around_operator(
    &mut self,
    line: &LogicalLine,
    context: &mut LogicalLinesContext,
) {
    self.operator_parens = 0;
    self.operator_fstrings = 0;
    self.operator_flags = 0;
    self.operator_cursor = 0;
    let mut tokens = line.tokens().iter().peekable();
    let first_token = tokens
        .by_ref()
        .find(|token| !is_non_logical_token(token.kind()));
    let Some(mut prev_token) = first_token else {
        return;
    };
    self.operator_parens = u32::from(matches!(
        prev_token.kind(),
        TokenKind::Lpar | TokenKind::Lambda
    ));
    self.operator_fstrings = u32::from(matches!(prev_token.kind(), TokenKind::FStringStart));

    while let Some(token) = tokens.next() {
        let kind = token.kind();
        let _classified = self.operator_classifies_token(kind);
        self.visit_token_kind(kind);

        if is_non_logical_token(kind) {
            continue;
        }

        match kind {
            TokenKind::FStringStart => {
                self.operator_fstrings = self.operator_fstrings.saturating_add(1);
                self.operator_flags = self.operator_flags.saturating_add(1);
            }
            TokenKind::FStringEnd => {
                self.operator_fstrings = self.operator_fstrings.saturating_sub(1);
                self.operator_flags = self.operator_flags.saturating_add(1);
            }
            TokenKind::Lpar | TokenKind::Lambda => {
                self.operator_parens = self.operator_parens.saturating_add(1);
                self.operator_cursor = self.operator_cursor.saturating_add(1);
            }
            TokenKind::Rpar => {
                self.operator_parens = self.operator_parens.saturating_sub(1);
                self.operator_cursor = self.operator_cursor.saturating_add(1);
            }
            _ => {}
        };

        let needs_space = if kind == TokenKind::Equal
            && (self.operator_parens > 0
                || self.operator_fstrings > 0
                || self.in_type_params())
        {
            OperatorSpaceNeed::No
        } else if kind == TokenKind::Slash {
            let slash_in_func = matches!(
                tokens.peek().map(|t| t.kind()),
                Some(TokenKind::Comma | TokenKind::Rpar | TokenKind::Colon)
            );
            OperatorSpaceNeed::from(!slash_in_func)
        } else if kind.is_unary_arithmetic_operator()
            || matches!(kind, TokenKind::Star | TokenKind::DoubleStar)
        {
            let prev_kind = prev_token.kind();
            let is_binary = matches!(
                prev_kind,
                TokenKind::Rpar | TokenKind::Rsqb | TokenKind::Rbrace
            ) || !(prev_kind.is_operator() || prev_kind.is_keyword());

            if is_binary {
                if kind == TokenKind::DoubleStar {
                    OperatorSpaceNeed::Optional
                } else {
                    OperatorSpaceNeed::Yes
                }
            } else {
                OperatorSpaceNeed::No
            }
        } else if tokens.peek().is_some_and(|token| {
            matches!(
                token.kind(),
                TokenKind::Rpar | TokenKind::Rsqb | TokenKind::Rbrace
            )
        }) {
            OperatorSpaceNeed::No
        } else if whitespace_around_named_parameter_equals::operator_needs_space(kind) {
            OperatorSpaceNeed::Yes
        } else {
            OperatorSpaceNeed::No
        };

        if needs_space != OperatorSpaceNeed::No {
            let has_leading_trivia =
                prev_token.end() < token.start() || is_non_logical_token(prev_token.kind());

            let has_trailing_trivia = tokens.peek().map_or(true, |next| {
                token.end() < next.start() || is_non_logical_token(next.kind())
            });

            match (has_leading_trivia, has_trailing_trivia) {
                (false, true) => {
                    let mut diagnostic = Diagnostic::new(
                        whitespace_around_named_parameter_equals::operator_diagnostic_kind(kind),
                        token.range(),
                    );
                    diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                        " ".to_string(),
                        token.start(),
                    )));
                    context.push_diagnostic(diagnostic);
                }
                (true, false) => {
                    let mut diagnostic = Diagnostic::new(
                        whitespace_around_named_parameter_equals::operator_diagnostic_kind(kind),
                        token.range(),
                    );
                    diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                        " ".to_string(),
                        token.end(),
                    )));
                    context.push_diagnostic(diagnostic);
                }
                (false, false) => {
                    if needs_space == OperatorSpaceNeed::Yes {
                        let mut diagnostic = Diagnostic::new(
                            whitespace_around_named_parameter_equals::operator_diagnostic_kind(kind),
                            token.range(),
                        );
                        diagnostic.set_fix(Fix::safe_edits(
                            Edit::insertion(" ".to_string(), token.start()),
                            [Edit::insertion(" ".to_string(), token.end())],
                        ));
                        context.push_diagnostic(diagnostic);
                    }
                }
                (true, true) => {}
            }
        }

        prev_token = token;
    }
}

pub(super) fn check_space_around_operator(
    &mut self,
    line: &LogicalLine,
    context: &mut LogicalLinesContext,
) {
    self.space_after_operator = 0;
    self.space_flags = 0;
    self.space_cursor = 0;

    for token in line.tokens() {
        let is_operator = space_around_operator::is_spacing_operator_token(token.kind());
        let _classified = self.space_classifies_token(token.kind());
        if is_operator {
            if self.space_after_operator == 0 {
                match line.leading_whitespace(token) {
                    (Whitespace::Tab, offset) => {
                        let mut diagnostic = Diagnostic::new(
                            TabBeforeOperator,
                            TextRange::at(token.start() - offset, offset),
                        );
                        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                            " ".to_string(),
                            TextRange::at(token.start() - offset, offset),
                        )));
                        context.push_diagnostic(diagnostic);
                    }
                    (Whitespace::Many, offset) => {
                        let mut diagnostic = Diagnostic::new(
                            MultipleSpacesBeforeOperator,
                            TextRange::at(token.start() - offset, offset),
                        );
                        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                            " ".to_string(),
                            TextRange::at(token.start() - offset, offset),
                        )));
                        context.push_diagnostic(diagnostic);
                    }
                    _ => {}
                }
            }

            match line.trailing_whitespace(token) {
                (Whitespace::Tab, len) => {
                    let mut diagnostic =
                        Diagnostic::new(TabAfterOperator, TextRange::at(token.end(), len));
                    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                        " ".to_string(),
                        TextRange::at(token.end(), len),
                    )));
                    context.push_diagnostic(diagnostic);
                }
                (Whitespace::Many, len) => {
                    let mut diagnostic = Diagnostic::new(
                        MultipleSpacesAfterOperator,
                        TextRange::at(token.end(), len),
                    );
                    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                        " ".to_string(),
                        TextRange::at(token.end(), len),
                    )));
                    context.push_diagnostic(diagnostic);
                }
                _ => {}
            }
            self.space_flags = self.space_flags.saturating_add(1);
        }
        self.space_after_operator = u32::from(is_operator);
        self.space_cursor = self.space_cursor.saturating_add(1);
    }
}

pub(super) fn check_space_after_comma(&mut self, line: &LogicalLine, context: &mut LogicalLinesContext) {
    self.space_flags = self.space_flags.saturating_add(1);
    self.space_cursor = self.space_cursor.saturating_add(1);
    for token in line.tokens() {
        let _classified = self.space_classifies_token(token.kind());
        if matches!(token.kind(), TokenKind::Comma) {
            match line.trailing_whitespace(token) {
                (Whitespace::Tab, len) => {
                    let mut diagnostic =
                        Diagnostic::new(TabAfterComma, TextRange::at(token.end(), len));
                    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                        " ".to_string(),
                        TextRange::at(token.end(), len),
                    )));
                    context.push_diagnostic(diagnostic);
                }
                (Whitespace::Many, len) => {
                    let mut diagnostic =
                        Diagnostic::new(MultipleSpacesAfterComma, TextRange::at(token.end(), len));
                    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                        " ".to_string(),
                        TextRange::at(token.end(), len),
                    )));
                    context.push_diagnostic(diagnostic);
                }
                _ => {}
            }
            self.space_flags = self.space_flags.saturating_add(1);
        }
        self.space_cursor = self.space_cursor.saturating_add(1);
    }
}

